import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');
  const [allUsers, setAllUsers] = useState([]);
  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState([
    { sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }
  ]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef(null);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'students') return user?.role === 'instructor' ? `courses?instructorid=${user.id}` : 'courses';
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    if (pageName === 'instructors') return 'users?role=instructor';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'instructors') return { name: '', email: '', courseTitle: '', courseDescription: '', courseSyllabus: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage(res.data.role === 'admin' ? 'instructors' : res.data.role === 'instructor' ? 'students' : 'courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setData([]);
    setCourses([]);
    setAssignments([]);
    setEnrolledCourseIds([]);
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setCurrentSubmissionText('');
    setShowGradeModal(false);
    setSubmissionToGrade(null);
    setGradeValue('');
    setFeedbackText('');
    setShowConfirmDelete(false);
    setItemToDelete(null);
    setDeleteBase('');
    setAllUsers([]);
    setShowChat(false);
    setChatMessages([{ sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }]);
    setChatInput('');
    setChatLoading(false);
  };

  const fetchData = async () => {
    setLoading(true);
    try {
      const endpoint = getEndpoint(page);
      if (endpoint) {
        const res = await axios.get(`${API}/${endpoint}`);
        setData(res.data);
      }
      if (user?.role === 'student') {
        const courseRes = await axios.get(`${API}/courses`);
        const enrolled = courseRes.data.filter(course => course.students?.includes(user.id) || course.students?.includes(user.id.toString()));
        setCourses(enrolled);
        setEnrolledCourseIds(enrolled.map(c => c.id));
      } else if (user?.role === 'instructor') {
        const courseRes = await axios.get(`${API}/courses?instructorid=${user.id}`);
        setCourses(courseRes.data);
      } else if (user?.role === 'admin') {
        const userRes = await axios.get(`${API}/users`);
        setAllUsers(userRes.data);
      }
    } catch (err) {
      console.error(err);
    }
    setLoading(false);
  };

  useEffect(() => {
    if (user) fetchData();
  }, [page, user]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const handleNav = (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    setFormData(getEmptyForm(newPage));
  };

  const handleInput = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const submitForm = async (e) => {
    e.preventDefault();
    try {
      let res;
      if (page === 'instructors') {
        const instructorData = { name: formData.name, email: formData.email, role: 'instructor' };
        const instructorRes = await axios.post(`${API}/users`, instructorData);
        const courseData = { title: formData.courseTitle, description: formData.courseDescription, syllabus: formData.courseSyllabus, instructorid: instructorRes.data.id };
        res = await axios.post(`${API}/courses`, courseData);
      } else {
        const base = page;
        if (editingItem) {
          res = await axios.put(`${API}/${base}/${editingItem.id}`, formData);
        } else {
          res = await axios.post(`${API}/${base}`, formData);
        }
      }
      fetchData();
      setShowForm(false);
      setEditingItem(null);
      setFormData(getEmptyForm(page));
    } catch (err) {
      alert('Error submitting form');
    }
  };

  const startEdit = (item) => {
    setEditingItem(item);
    setFormData(item);
    setShowForm(true);
  };

  const confirmDelete = (item, base) => {
    setItemToDelete(item);
    setDeleteBase(base);
    setShowConfirmDelete(true);
  };

  const handleDelete = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete.id}`);
      fetchData();
    } catch (err) {
      alert('Error deleting');
    }
    setShowConfirmDelete(false);
    setItemToDelete(null);
    setDeleteBase('');
  };

  const enrollInCourse = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      fetchData();
    } catch (err) {
      alert('Enrollment failed');
    }
  };

  const dropCourse = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      fetchData();
    } catch (err) {
      alert('Drop failed');
    }
  };

  const fetchAssignments = async (courseId) => {
    try {
      const res = await axios.get(`${API}/assignments?courseid=${courseId}`);
      setAssignments(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const selectAssignment = (assignment) => {
    setSelectedAssignment(assignment);
    setSubmissionText('');
  };

  const submitAssignment = async () => {
    if (!submissionText.trim()) return alert('Please enter submission text');
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: selectedAssignment.id,
        studentid: user.id,
        fileurl: submissionText  // Using text as "file" for demo
      });
      alert('Submitted!');
      setSelectedAssignment(null);
      setSubmissionText('');
      fetchData();
    } catch (err) {
      alert('Submission failed');
    }
  };

  const viewSubmission = (text) => {
    setCurrentSubmissionText(text);
    setShowFileModal(true);
  };

  const gradeSubmission = (submission) => {
    setSubmissionToGrade(submission);
    setGradeValue(submission.grade || '');
    setFeedbackText(submission.feedback || '');
    setShowGradeModal(true);
  };

  const submitGrade = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, {
        grade: gradeValue,
        feedback: feedbackText
      });
      alert('Grade submitted!');
      setShowGradeModal(false);
      setSubmissionToGrade(null);
      setGradeValue('');
      setFeedbackText('');
      fetchData();
    } catch (err) {
      alert('Grading failed');
    }
  };

  const sendChatMessage = async (e) => {
    e.preventDefault();
    if (!chatInput.trim()) return;
    const userMessage = { sender: 'user', text: chatInput };
    setChatMessages(prev => [...prev, userMessage]);
    setChatInput('');
    setChatLoading(true);
    try {
      const res = await axios.post(`${API}/chat`, { message: chatInput });
      const botMessage = { sender: 'bot', text: res.data.reply };
      setChatMessages(prev => [...prev, botMessage]);
    } catch (err) {
      const errorMessage = { sender: 'bot', text: 'Sorry, there was an error. Please try again.' };
      setChatMessages(prev => [...prev, errorMessage]);
    }
    setChatLoading(false);
  };

  const navLinks = user?.role === 'admin' ? [
    { page: 'instructors', label: 'Manage Instructors' },
    { page: 'students', label: 'View Students' }
  ] : user?.role === 'instructor' ? [
    { page: 'students', label: 'My Courses' },
    { page: 'assignments', label: 'Assignments' },
    { page: 'announcements', label: 'Announcements' },
    { page: 'submissions', label: 'Submissions' }
  ] : [
    { page: 'courses', label: 'Courses' },
    { page: 'assignments', label: 'Assignments' },
    { page: 'announcements', label: 'Announcements' },
    { page: 'submissions', label: 'My Submissions' }
  ];

  return (
    <div style={{ minHeight: '100vh', background: '#667eea', color: 'white' }}>
      {page === 'login' ? (
        <div style={{ maxWidth: '400px', margin: '100px auto', background: 'white', color: '#333', padding: '40px', borderRadius: '20px', boxShadow: '0 10px 30px rgba(0,0,0,0.4)' }}>
          <h1 style={{ textAlign: 'center', marginBottom: '30px', color: '#333' }}>NM Student Portal</h1>
          <form onSubmit={login} style={{ display: 'flex', flexDirection: 'column' }}>
            <input
              type="email"
              placeholder="Enter your email (e.g., nm@sportal.com)"
              value={emailInput}
              onChange={e => setEmailInput(e.target.value)}
              style={{ padding: '15px', marginBottom: '20px', borderRadius: '10px', border: '1px solid #ddd' }}
            />
            <button type="submit" style={{ padding: '15px', background: '#4facfe', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer' }}>Login</button>
          </form>
        </div>
      ) : (
        <>
          <header>
            <nav style={{ background: '#333', padding: '15px', textAlign: 'center' }}>
              {navLinks.map(link => (
                <button key={link.page} onClick={() => handleNav(link.page)} style={{ margin: '0 10px', padding: '10px 20px', background: page === link.page ? '#00c9ff' : '#4facfe', color: 'white', border: 'none', borderRadius: '50px', cursor: 'pointer' }}>
                  {link.label}
                </button>
              ))}
              <button onClick={() => setShowChat(true)} style={{ margin: '0 10px', padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '50px', cursor: 'pointer' }}>
                AI Chat
              </button>
              {user && <button onClick={logout} style={{ marginLeft: '20px', padding: '10px 20px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '50px', cursor: 'pointer' }}>Logout</button>}
            </nav>
          </header>
          <main>
            <div className="container" style={{ maxWidth: '1000px', margin: '30px auto', background: 'white', color: '#333', padding: '40px', borderRadius: '20px', boxShadow: '0 10px 30px rgba(0,0,0,0.4)' }}>
              <h1 style={{ marginBottom: '30px' }}>{user?.name} - {user?.role.charAt(0).toUpperCase() + user?.role.slice(1)} Dashboard</h1>

              {loading ? <p style={{ textAlign: 'center' }}>Loading...</p> : (
                <>
                  {/* Admin: Manage Instructors */}
                  {user?.role === 'admin' && page === 'instructors' && (
                    <>
                      <button onClick={() => { setShowForm(true); setFormData(getEmptyForm(page)); setEditingItem(null); }} style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginBottom: '20px' }}>Add Instructor + Course</button>
                      {showForm && (
                        <form onSubmit={submitForm} style={{ background: '#f7fafc', padding: '20px', borderRadius: '12px', marginBottom: '30px' }}>
                          <h3>{editingItem ? 'Edit' : 'Add'} Instructor and Course</h3>
                          <input name="name" placeholder="Instructor Name" value={formData.name || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }} />
                          <input name="email" placeholder="Instructor Email" value={formData.email || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }} />
                          <input name="courseTitle" placeholder="Course Title" value={formData.courseTitle || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }} />
                          <textarea name="courseDescription" placeholder="Course Description" value={formData.courseDescription || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd', minHeight: '100px' }} />
                          <textarea name="courseSyllabus" placeholder="Course Syllabus" value={formData.courseSyllabus || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd', minHeight: '100px' }} />
                          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                            <button type="submit" style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginRight: '10px' }}>{editingItem ? 'Update' : 'Add'}</button>
                            <button type="button" onClick={() => setShowForm(false)} style={{ padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                          </div>
                        </form>
                      )}
                      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                        <thead>
                          <tr>
                            <th>Name</th>
                            <th>Email</th>
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {data.map(instructor => (
                            <tr key={instructor.id}>
                              <td>{instructor.name}</td>
                              <td>{instructor.email}</td>
                              <td>
                                <button onClick={() => startEdit(instructor)} style={{ padding: '6px 12px', background: '#ecc94b', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', marginRight: '5px' }}>Edit</button>
                                <button onClick={() => confirmDelete(instructor, 'users')} style={{ padding: '6px 12px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Delete</button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </>
                  )}

                  {/* Admin: View Students */}
                  {user?.role === 'admin' && page === 'students' && (
                    <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                      <thead>
                        <tr>
                          <th>Name</th>
                          <th>Email</th>
                          <th>Role</th>
                        </tr>
                      </thead>
                      <tbody>
                        {allUsers.filter(u => u.role === 'student').map(student => (
                          <tr key={student.id}>
                            <td>{student.name}</td>
                            <td>{student.email}</td>
                            <td>{student.role}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  )}

                  {/* Instructor: My Courses (Students) */}
                  {user?.role === 'instructor' && page === 'students' && (
                    <>
                      <h2>My Courses</h2>
                      {courses.map(course => (
                        <div key={course.id} style={{ background: '#f7fafc', padding: '20px', borderRadius: '12px', marginBottom: '20px' }}>
                          <h3>{course.title}</h3>
                          <p>{course.description}</p>
                          <p><strong>Syllabus:</strong> {course.syllabus}</p>
                          <h4>Enrolled Students:</h4>
                          <ul>
                            {course.students?.map(studentId => {
                              const student = allUsers.find(u => u.id === parseInt(studentId));
                              return student ? <li key={studentId}>{student.name} ({student.email})</li> : null;
                            })}
                          </ul>
                        </div>
                      ))}
                    </>
                  )}

                  {/* Instructor/Student: Assignments */}
                  {(page === 'assignments') && (
                    <>
                      {user?.role === 'instructor' && (
                        <button onClick={() => { setShowForm(true); setFormData(getEmptyForm(page)); setEditingItem(null); }} style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginBottom: '20px' }}>Add Assignment</button>
                      )}
                      {showForm && user?.role === 'instructor' && (
                        <form onSubmit={submitForm} style={{ background: '#f7fafc', padding: '20px', borderRadius: '12px', marginBottom: '30px' }}>
                          <h3>{editingItem ? 'Edit' : 'Add'} Assignment</h3>
                          <select name="courseid" value={formData.courseid || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }}>
                            <option value="">Select Course</option>
                            {courses.map(course => <option key={course.id} value={course.id}>{course.title}</option>)}
                          </select>
                          <input name="title" placeholder="Title" value={formData.title || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }} />
                          <input name="duedate" type="date" value={formData.duedate || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }} />
                          <textarea name="description" placeholder="Description" value={formData.description || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd', minHeight: '100px' }} />
                          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                            <button type="submit" style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginRight: '10px' }}>{editingItem ? 'Update' : 'Add'}</button>
                            <button type="button" onClick={() => setShowForm(false)} style={{ padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                          </div>
                        </form>
                      )}
                      <h2>Assignments</h2>
                      {courses.map(course => (
                        <div key={course.id}>
                          <h3 onClick={() => fetchAssignments(course.id)} style={{ cursor: 'pointer', background: '#e2e8f0', padding: '10px', borderRadius: '8px', margin: '10px 0' }}>{course.title} Assignments</h3>
                          {assignments.filter(a => a.courseid === course.id).map(assignment => (
                            <div key={assignment.id} style={{ background: '#f7fafc', padding: '15px', borderRadius: '8px', marginBottom: '10px' }}>
                              <h4>{assignment.title}</h4>
                              <p>Due: {assignment.duedate}</p>
                              <p>{assignment.description}</p>
                              {user?.role === 'student' && (
                                <button onClick={() => selectAssignment(assignment)} style={{ padding: '8px 16px', background: '#4facfe', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Submit</button>
                              )}
                              {user?.role === 'instructor' && (
                                <>
                                  <button onClick={() => startEdit(assignment)} style={{ padding: '8px 16px', background: '#ecc94b', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginRight: '5px' }}>Edit</button>
                                  <button onClick={() => confirmDelete(assignment, 'assignments')} style={{ padding: '8px 16px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Delete</button>
                                </>
                              )}
                            </div>
                          ))}
                        </div>
                      ))}
                      {selectedAssignment && user?.role === 'student' && (
                        <div style={{ marginTop: '20px', background: '#f7fafc', padding: '20px', borderRadius: '12px' }}>
                          <h3>Submit {selectedAssignment.title}</h3>
                          <textarea
                            placeholder="Enter your submission text here..."
                            value={submissionText}
                            onChange={e => setSubmissionText(e.target.value)}
                            style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd', minHeight: '150px' }}
                          />
                          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                            <button onClick={submitAssignment} style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginRight: '10px' }}>Submit</button>
                            <button onClick={() => setSelectedAssignment(null)} style={{ padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                          </div>
                        </div>
                      )}
                    </>
                  )}

                  {/* Instructor/Student: Announcements */}
                  {page === 'announcements' && (
                    <>
                      {user?.role === 'instructor' && (
                        <button onClick={() => { setShowForm(true); setFormData(getEmptyForm(page)); setEditingItem(null); }} style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginBottom: '20px' }}>Add Announcement</button>
                      )}
                      {showForm && user?.role === 'instructor' && (
                        <form onSubmit={submitForm} style={{ background: '#f7fafc', padding: '20px', borderRadius: '12px', marginBottom: '30px' }}>
                          <h3>{editingItem ? 'Edit' : 'Add'} Announcement</h3>
                          <select name="courseid" value={formData.courseid || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }}>
                            <option value="">Select Course</option>
                            {courses.map(course => <option key={course.id} value={course.id}>{course.title}</option>)}
                          </select>
                          <input name="title" placeholder="Title" value={formData.title || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }} />
                          <textarea name="message" placeholder="Message" value={formData.message || ''} onChange={handleInput} style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd', minHeight: '100px' }} />
                          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                            <button type="submit" style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginRight: '10px' }}>{editingItem ? 'Update' : 'Add'}</button>
                            <button type="button" onClick={() => setShowForm(false)} style={{ padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                          </div>
                        </form>
                      )}
                      <h2>Announcements</h2>
                      {courses.map(course => (
                        <div key={course.id}>
                          <h3>{course.title} Announcements</h3>
                          {data.filter(a => a.courseid === course.id).map(ann => (
                            <div key={ann.id} style={{ background: '#f7fafc', padding: '15px', borderRadius: '8px', marginBottom: '10px' }}>
                              <h4>{ann.title}</h4>
                              <p>{ann.message}</p>
                              <p><small>Posted: {ann.dateposted}</small></p>
                              {user?.role === 'instructor' && (
                                <>
                                  <button onClick={() => startEdit(ann)} style={{ padding: '8px 16px', background: '#ecc94b', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginRight: '5px' }}>Edit</button>
                                  <button onClick={() => confirmDelete(ann, 'announcements')} style={{ padding: '8px 16px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Delete</button>
                                </>
                              )}
                            </div>
                          ))}
                        </div>
                      ))}
                    </>
                  )}

                  {/* Student: Courses */}
                  {user?.role === 'student' && page === 'courses' && (
                    <>
                      <h2>Available Courses</h2>
                      {data.map(course => (
                        <div key={course.id} style={{ background: '#f7fafc', padding: '20px', borderRadius: '12px', marginBottom: '20px' }}>
                          <h3>{course.title}</h3>
                          <p>{course.description}</p>
                          <p><strong>Syllabus:</strong> {course.syllabus}</p>
                          <p><strong>Instructor:</strong> {allUsers.find(u => u.id === course.instructorid)?.name}</p>
                          {enrolledCourseIds.includes(course.id) ? (
                            <button onClick={() => dropCourse(course.id)} style={{ padding: '10px 20px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Drop Course</button>
                          ) : (
                            <button onClick={() => enrollInCourse(course.id)} style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Enroll</button>
                          )}
                        </div>
                      ))}
                    </>
                  )}

                  {/* Submissions */}
                  {page === 'submissions' && (
                    <>
                      <h2>{user?.role === 'student' ? 'My Submissions' : 'Student Submissions'}</h2>
                      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                        <thead>
                          <tr>
                            <th>Assignment</th>
                            <th>{user?.role === 'student' ? 'Grade' : 'Student'}</th>
                            <th>Submission</th>
                            {user?.role === 'instructor' && <th>Actions</th>}
                          </tr>
                        </thead>
                        <tbody>
                          {data.map(sub => {
                            const assignment = assignments.find(a => a.id === sub.assignmentid);
                            const student = allUsers.find(u => u.id === sub.studentid);
                            return (
                              <tr key={sub.id}>
                                <td>{assignment?.title}</td>
                                <td>{user?.role === 'student' ? (sub.grade || 'Ungraded') : (student?.name || 'Unknown')}</td>
                                <td>
                                  <button onClick={() => viewSubmission(sub.fileurl)} style={{ padding: '6px 12px', background: '#4facfe', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>View</button>
                                </td>
                                {user?.role === 'instructor' && (
                                  <td>
                                    <button onClick={() => gradeSubmission(sub)} style={{ padding: '6px 12px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Grade</button>
                                  </td>
                                )}
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </>
                  )}
                </>
              )}

              {/* Grade Modal */}
              {showGradeModal && (
                <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
                  <div style={{ background: 'white', padding: '30px', borderRadius: '12px', maxWidth: '500px', width: '90%' }}>
                    <h3>Grade Submission</h3>
                    <form onSubmit={submitGrade}>
                      <input
                        type="number"
                        placeholder="Grade (0-100)"
                        value={gradeValue}
                        onChange={e => setGradeValue(e.target.value)}
                        style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd' }}
                      />
                      <textarea
                        placeholder="Feedback"
                        value={feedbackText}
                        onChange={e => setFeedbackText(e.target.value)}
                        style={{ display: 'block', width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '1px solid #ddd', minHeight: '100px' }}
                      />
                      <div style={{ marginTop: '20px' }}>
                        <button type="submit" style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginRight: '10px' }}>Submit Grade</button>
                        <button type="button" onClick={() => { setShowGradeModal(false); setSubmissionToGrade(null); setGradeValue(''); setFeedbackText(''); }} style={{ padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                      </div>
                    </form>
                  </div>
                </div>
              )}

              {/* View Submission Text Modal */}
              {showFileModal && (
                <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
                  <div style={{ background: 'white', padding: '30px', borderRadius: '12px', maxWidth: '800px', width: '90%', maxHeight: '80vh', overflowY: 'auto' }}>
                    <h3 style={{ margin: '0 0 20px' }}>Submission Text</h3>
                    <p style={{ whiteSpace: 'pre-wrap', background: '#f7fafc', padding: '20px', borderRadius: '8px', minHeight: '200px' }}>
                      {currentSubmissionText || 'No content'}
                    </p>
                    <button onClick={() => setShowFileModal(false)} style={{ padding: '10px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>
                      Close
                    </button>
                  </div>
                </div>
              )}

              {/* Confirm Delete Modal */}
              {showConfirmDelete && (
                <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
                  <div style={{ background: 'white', padding: '30px', borderRadius: '12px', textAlign: 'center' }}>
                    <h3>Are you sure you want to delete?</h3>
                    <div style={{ marginTop: '20px' }}>
                      <button onClick={handleDelete} style={{ marginRight: '10px', padding: '10px 20px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Yes, Delete</button>
                      <button onClick={() => { setShowConfirmDelete(false); setItemToDelete(null); setDeleteBase(''); }} style={{ padding: '10px 20px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                    </div>
                  </div>
                </div>
              )}

              {/* AI Chat Window */}
              {showChat && (
                <div style={{ position: 'fixed', bottom: '20px', right: '20px', width: '300px', height: '400px', background: 'white', color: 'black', borderRadius: '10px', boxShadow: '0 0 10px rgba(0,0,0,0.5)', display: 'flex', flexDirection: 'column', zIndex: 1000 }}>
                  <div style={{ padding: '10px', background: '#667eea', color: 'white', borderTopLeftRadius: '10px', borderTopRightRadius: '10px', display: 'flex', justifyContent: 'space-between' }}>
                    <h4 style={{ margin: 0 }}>AI Assistant</h4>
                    <button onClick={() => setShowChat(false)} style={{ background: 'none', border: 'none', color: 'white', cursor: 'pointer' }}>X</button>
                  </div>
                  <div style={{ flex: 1, overflowY: 'auto', padding: '10px' }}>
                    {chatMessages.map((msg, i) => (
                      <div key={i} style={{ textAlign: msg.sender === 'user' ? 'right' : 'left', marginBottom: '10px' }}>
                        <span style={{ background: msg.sender === 'user' ? '#bee3f8' : '#e2e8f0', padding: '8px', borderRadius: '10px', display: 'inline-block', maxWidth: '80%' }}>
                          {msg.text}
                        </span>
                      </div>
                    ))}
                    {chatLoading && <div style={{ textAlign: 'center' }}>Loading...</div>}
                    <div ref={chatEndRef} />
                  </div>
                  <form onSubmit={sendChatMessage} style={{ display: 'flex', padding: '10px', borderTop: '1px solid #ddd' }}>
                    <input
                      value={chatInput}
                      onChange={e => setChatInput(e.target.value)}
                      placeholder="Type your question..."
                      style={{ flex: 1, padding: '8px', borderRadius: '5px', border: '1px solid #ddd' }}
                    />
                    <button type="submit" style={{ padding: '8px 12px', background: '#4facfe', color: 'white', border: 'none', borderRadius: '5px', marginLeft: '5px', cursor: 'pointer' }}>Send</button>
                  </form>
                </div>
              )}

            </div>
          </main>
          <footer style={{ textAlign: 'center', padding: '30px', color: 'white', background: 'rgba(0,0,0,0.3)', marginTop: '50px' }}>
            <h3 style={{ margin: '0 0 10px' }}>Student Portal © 2025</h3>
            <p style={{ margin: 0, opacity: 0.9 }}>Nikko Manuel - Marlon Chipa Learning Management System</p>
          </footer>
        </>
      )}
    </div>
  );
}

export default App;
